/* SiteArchitect 11 — static front end + Supabase Auth / Postgres RLS */
(() => {
  'use strict';
  const root = document.getElementById('app');
  const toastNode = document.getElementById('toast');
  const cfg = window.SITEARCHITECT_CONFIG || {};
  const configured = /^https:\/\/[\w.-]+\.supabase\.co\/?$/.test((cfg.supabaseUrl || '').trim()) && !!(cfg.supabasePublishableKey || '').trim();
  const cloud = configured && !!window.supabase;
  const db = cloud ? window.supabase.createClient(cfg.supabaseUrl, cfg.supabasePublishableKey, { auth: { persistSession: true, autoRefreshToken: true } }) : null;
  const demo = !configured;
  const state = { page:'dashboard', step:0, authMode:'login', profile:null, user:null,
    works:[], teacherWorks:[], profiles:[], work:null, selected:'home',
    teacherQuery:'', teacherStatus:'submitted', teacherClass:'all', viewed:null,
    busy:false, authMessage:'', authError:'', demoProfile: null };
  const steps = ['Паспорт', 'Контент', 'Групування', 'Дерево сайту', 'Результат'];
  const kindLabels = {portfolio:'Портфоліо',visit:'Сайт-візитка',education:'Освітній сайт',shop:'Інтернет-магазин',blog:'Блог / медіа',event:'Подієвий сайт',other:'Інший тип'};
  const structureLabels = {hierarchical:'Ієрархічна',linear:'Лінійна',hybrid:'Гібридна',network:'Мережева'};
  const orgLabels = {topic:'За тематикою',audience:'За цільовою аудиторією',task:'За завданням користувача',time:'За хронологією',other:'Власна логіка'};
  const uid = () => (window.crypto && crypto.randomUUID) ? crypto.randomUUID() : `id-${Date.now()}-${Math.floor(Math.random()*1e8)}`;
  const h = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const clip = (v, n=250) => String(v ?? '').slice(0,n);
  const clone = obj => JSON.parse(JSON.stringify(obj));
  const fmtDate = date => date ? new Date(date).toLocaleString('uk-UA', {dateStyle:'medium', timeStyle:'short'}) : '—';
  const safeFilename = name => (name || 'struktura').replace(/[^a-zA-Zа-яА-ЯіІїЇєЄґҐ0-9_-]+/g,'_').slice(0,70);
  let toastTimer;
  function toast(msg, bad=false){ toastNode.textContent=msg; toastNode.className='toast show'+(bad?' error':''); clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastNode.className='toast',4300); }
  function emptyWork(){return {name:'',topic:'',goal:'',kind:'',audience:'',structure:'hierarchical',organize:'topic',nodes:[{id:'home',type:'home',label:'Головна',description:'Перший екран і короткий огляд сайта',blocks:['Головний банер','Меню навігації','Короткий вступ'],parentId:null,order:0}],links:[]};}
  function mkNode(type,label,parentId='home',description='',blocks=[]){return{id:uid(),type,label,description,blocks:blocks.slice(),parentId,order:999};}
  function getNode(p,id){return (p?.nodes||[]).find(n=>n.id===id);}
  function children(p,pid){return (p?.nodes||[]).filter(n=>n.parentId===pid).sort((a,b)=>(a.order||0)-(b.order||0));}
  function flatTree(p){const result=[];const seen=new Set();function go(id,depth){if(seen.has(id))return;const node=getNode(p,id);if(!node)return;seen.add(id);result.push({node,depth});children(p,id).forEach(n=>go(n.id,depth+1));}go('home',0);return result;}
  function countPages(p){return (p?.nodes||[]).filter(n=>n.type==='page').length;}
  function depthOf(p,id){let d=0,cur=getNode(p,id);const seen=new Set();while(cur?.parentId && !seen.has(cur.parentId)){seen.add(cur.parentId);d++;cur=getNode(p,cur.parentId);if(d>25)break;}return d;}
  function isDescendant(p,candidate,of){let cur=getNode(p,candidate),s=new Set();while(cur?.parentId&&!s.has(cur.parentId)){if(cur.parentId===of)return true;s.add(cur.parentId);cur=getNode(p,cur.parentId);}return false;}
  const translit = {'а':'a','б':'b','в':'v','г':'h','ґ':'g','д':'d','е':'e','є':'ye','ж':'zh','з':'z','и':'y','і':'i','ї':'yi','й':'i','к':'k','л':'l','м':'m','н':'n','о':'o','п':'p','р':'r','с':'s','т':'t','у':'u','ф':'f','х':'kh','ц':'ts','ч':'ch','ш':'sh','щ':'shch','ь':'','ю':'yu','я':'ya','ы':'y','э':'e','ё':'yo','ъ':''};
  function slug(text){const latin=String(text||'page').toLowerCase().split('').map(c=>translit[c]??c).join('');return latin.replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,52)||'page';}
  function filePath(p,id){let n=getNode(p,id);if(!n)return '—';if(n.type==='home')return 'index.html';const parts=[],seen=new Set();while(n&&n.id!=='home'&&!seen.has(n.id)){seen.add(n.id);parts.unshift(slug(n.label)+(n.type==='folder'?'/':'.html'));n=getNode(p,n.parentId);}return parts.join('');}
  function templates(key){const p=emptyWork();const add=(type,label,parent,description,blocks)=>{const n=mkNode(type,label,parent,description,blocks);n.order=children(p,parent).length;p.nodes.push(n);return n.id;};
    if(key==='portfolio') {p.name='Моє портфоліо';p.kind='portfolio';add('page','Про мене','home','Біографія, навички й інтереси',['Фото та знайомство','Мої навички','Мета розвитку']);const folder=add('folder','Мої проєкти','home','Добірка найкращих робіт',[]);add('page','Вебпроєкти',folder,'Мої сайти та макети',['Галерея','Опис проєктів']);add('page','Творчі роботи',folder,'Творчі досягнення',['Приклади робіт','Опис процесу']);add('page','Досягнення','home','Сертифікати й конкурси',['Сертифікати','Нагороди']);add('page','Контакти','home','Способи зв’язку',['Форма звернення','Соціальні мережі']);}
    else if(key==='education') {p.name='Навчальна платформа';p.kind='education';const f=add('folder','Навчальні матеріали','home','Матеріали, упорядковані за предметами',[]);add('page','Інформатика',f,'Уроки з інформатики',['Теми','Матеріали','Вправи']);add('page','Математика',f,'Уроки з математики',['Теми','Завдання']);add('page','Про платформу','home','Мета та можливості ресурсу',['Мета','Переваги']);const s=add('folder','Допомога','home','Підтримка користувачів',[]);add('page','Поширені питання',s,'Поради користувачам',['Питання та відповіді']);add('page','Контакти',s,'Зворотний зв’язок',['Контактна форма']);}
    else if(key==='shop') {p.name='Мій інтернет-магазин';p.kind='shop';const c=add('folder','Каталог','home','Товари за категоріями',[]);add('page','Категорія А',c,'Товари першої категорії',['Сітка товарів','Фільтри']);add('page','Категорія Б',c,'Товари другої категорії',['Сітка товарів','Сортування']);add('page','Кошик','home','Обрані покупки',['Перелік товарів','Підсумкова сума']);add('page','Доставка й оплата','home','Умови замовлення',['Способи доставки','Варіанти оплати']);add('page','Контакти','home','Допомога покупцям',['Адреса','Зворотний зв’язок']);}
    else if(key==='blog') {p.name='Авторський блог';p.kind='blog';const c=add('folder','Рубрики','home','Тематичні розділи статей',[]);add('page','Новини',c,'Нові повідомлення та дописи',['Стрічка дописів','Дати']);add('page','Поради',c,'Корисні інструкції',['Добірка статей']);add('page','Огляд матеріалу','home','Сторінка окремої публікації',['Заголовок','Текст','Ілюстрації']);add('page','Про автора','home','Інформація про автора',['Біографія','Інтереси']);add('page','Контакти','home','Спілкування з читачами',['Форма зворотного зв’язку']);}
    else if(key==='visit') {p.name='Сайт-візитка';p.kind='visit';add('page','Про нас','home','Історія та команда',['Історія','Цінності']);add('page','Послуги','home','Що ми пропонуємо',['Картки послуг','Переваги']);add('page','Портфоліо','home','Реалізовані проєкти',['Галерея','Відгуки']);add('page','Ціни','home','Перелік послуг і вартості',['Прайс']);add('page','Контакти','home','Адреса й засоби зв’язку',['Адреса','Контакти']);}
    return p;}
  function analysis(p){const pages=(p.nodes||[]).filter(n=>n.type==='page');const folders=(p.nodes||[]).filter(n=>n.type==='folder');const all=flatTree(p);const maxDepth=Math.max(0,...all.map(item=>item.depth));const specs=[
    {ok:!!(p.name.trim()&&p.topic.trim()&&p.goal.trim()&&p.kind&&p.audience.trim()),name:'Паспорт вебпроєкту',detail:'Назва, тема, мета, тип сайту та цільова аудиторія'},
    {ok:pages.length>=5,name:'Достатньо сторінок',detail:`Створено ${pages.length} із рекомендованих щонайменше 5 сторінок`},
    {ok:pages.length>0&&pages.every(n=>n.label.trim()&&n.description.trim()),name:'Описи сторінок',detail:'Кожна сторінка має назву та пояснення свого вмісту'},
    {ok:pages.length>0&&pages.every(n=>(n.blocks||[]).length>=2),name:'Контентні блоки',detail:'На кожній сторінці сплановано принаймні 2 змістові блоки'},
    {ok:pages.length<=6||folders.length>=1,name:'Логічне групування',detail:'Для великого сайту передбачено розділи / папки'},
    {ok:maxDepth<=3,name:'Зрозуміла глибина',detail:`Максимальна глибина: ${maxDepth} переходів від головної (орієнтир — до 3)`},
    {ok:folders.every(n=>children(p,n.id).length>0),name:'Немає порожніх розділів',detail:'У кожної папки є вкладені елементи'},
    {ok:!findDuplicates(p).length,name:'Однозначні назви',detail:'У межах одного розділу назви не дублюються'}
  ];const warnings=[];
    if(maxDepth>3)warnings.push('Знайдено сторінки глибше трьох переходів. Спробуй спростити навігацію або додати логічні швидкі посилання.');
    if(folders.length===0&&pages.length>=7)warnings.push('Усі сторінки на одному рівні. Для великого сайта подумай, чи варто об’єднати частину в розділи.');
    for(const f of folders){if(!children(p,f.id).length)warnings.push(`Розділ «${f.label}» порожній. Додай вміст або видали його.`);}
    const sizes=folders.filter(f=>f.parentId==='home').map(f=>({name:f.label,n:descPageCount(p,f.id)}));if(sizes.length>=2){const max=Math.max(...sizes.map(v=>v.n));const total=sizes.reduce((s,v)=>s+v.n,0);if(total>=6&&max/total>.8)warnings.push('Один розділ містить понад 80% згрупованих сторінок. Перевір баланс структури.');}
    for(const n of pages){if(!n.description.trim())warnings.push(`Додай опис сторінки «${n.label}».`); if(!(n.blocks||[]).length)warnings.push(`Заплануй блоки вмісту сторінки «${n.label}».`);}
    if(!p.audience.trim())warnings.push('Уточни цільову аудиторію: для кого саме створюється сайт?');
    if(p.structure==='linear'&&children(p,'home').length>1)warnings.push('Обрано лінійну структуру, але з головної сторінки виходять кілька гілок. Перевір відповідність задуму.');
    if((p.structure==='network'||p.structure==='hybrid')&&!(p.links||[]).length)warnings.push('Для мережевої або гібридної структури доцільно додати хоча б одне перехресне посилання.');
    return {specs,score:Math.round(specs.filter(s=>s.ok).length/specs.length*100),warnings,maxDepth,pages:pages.length,folders:folders.length};}
  function descPageCount(p,id){return p.nodes.filter(n=>n.type==='page'&&isDescendant(p,n.id,id)).length;}
  function findDuplicates(p){const seen=new Set(),dups=[];for(const n of p.nodes){const k=`${n.parentId||''}|${n.label.toLowerCase().trim()}`;if(seen.has(k))dups.push(n.label);seen.add(k);}return dups;}
  function validForSubmit(p){const a=analysis(p);return a.specs.slice(0,4).every(x=>x.ok) && a.specs[5].ok && a.specs[6].ok && a.specs[7].ok;}

  function renderAuth(){let mode=state.authMode;root.innerHTML=`<main class="auth-page"><section class="auth-intro">
     <div class="logo"><span class="logo-mark">⌘</span> SiteArchitect <b>11</b></div>
     <div style="margin-top:30px"><span class="eyebrow">Інформатика • 11 клас • практична місія</span></div>
     <h1 class="heading">Створи <span>архітектуру</span> свого майбутнього сайту.</h1>
     <p>Від ідеї до професійної карти сторінок. Придумай сайт, сплануй контент, згрупуй розділи та створи власне дерево навігації.</p>
     <div class="auth-features"><div class="auth-feature"><span class="feature-icon">01</span>Покроковий конструктор із підказками</div><div class="auth-feature"><span class="feature-icon">02</span>Автоматична схема і перевірка логіки</div><div class="auth-feature"><span class="feature-icon">03</span>Збереження роботи та експорт PNG</div></div>
     </section><section class="card auth-box"><span class="eyebrow">${demo?'Демонстраційна версія':'Простір учня та вчителя'}</span>
     <h2 class="h2" style="font-size:26px;margin-top:9px">${demo?'Ласкаво просимо!':mode==='login'?'Увійдіть до майстерні':'Створіть обліковий запис'}</h2>
     <p class="desc">${demo?'Почніть роботу без налаштування сервера. Проєкти зберігаються лише у цьому браузері.':mode==='login'?'Увійдіть, щоб продовжити роботу над власними проєктами.':'Укажіть справжнє ім’я та клас, щоб учитель упізнав вашу роботу.'}</p>
     ${demo?`<div class="notice warn" style="margin-bottom:17px">Деморежим: спільної бази та приватного кабінету вчителя поки немає. Для цього потрібно підключити Supabase за інструкцією у README.</div>
     <form id="demo-form"><div class="field"><label>Ім’я та прізвище</label><input name="fullName" required maxlength="100" placeholder="Олена Коваленко" value="${h(state.demoProfile?.full_name||'')}" /></div>
     <div class="field"><label>Клас</label><input name="className" required maxlength="20" placeholder="11-А" value="${h(state.demoProfile?.class_name||'')}" /></div>
     <button class="btn primary full" type="submit">Розпочати конструювання →</button></form>`:
     `<div class="auth-tabs"><button data-action="auth-mode" data-mode="login" class="${mode==='login'?'active':''}">Увійти</button><button data-action="auth-mode" data-mode="signup" class="${mode==='signup'?'active':''}">Реєстрація</button></div>
     <form id="auth-form">${mode==='signup'?`<div class="field"><label>Ім’я та прізвище</label><input name="fullName" required maxlength="100" placeholder="Олена Коваленко" /></div><div class="field"><label>Клас</label><input name="className" required maxlength="20" placeholder="11-А" /></div>`:''}
     <div class="field"><label>Електронна пошта</label><input type="email" name="email" autocomplete="email" required placeholder="student@example.com" /></div>
     <div class="field"><label>Пароль (не менше 6 символів)</label><input type="password" name="password" minlength="6" autocomplete="${mode==='signup'?'new-password':'current-password'}" required placeholder="••••••••" /></div>
     <button class="btn primary full" type="submit">${mode==='signup'?'Зареєструватися':'Увійти'} →</button></form>
     ${mode==='login'?`<button class="btn ghost full" style="margin-top:10px" data-action="reset-password">Забули пароль?</button>`:''}
     ${state.authMessage?`<div class="notice good" style="margin-top:13px">${h(state.authMessage)}</div>`:''}
     ${state.authError?`<div class="notice warn" style="margin-top:13px">${h(state.authError)}</div>`:''}`}
     <div class="auth-footer">SiteArchitect 11 · Тема: «Інформаційна структура сайту»<br/>${demo?'Для публікації потрібні GitHub Pages + Supabase.':'Усі проєкти зберігаються з розмежуванням прав доступу.'}</div></section></main>`;}
  function navLink(action,label,icon,active){return `<button class="nav-link ${active?'active':''}" data-action="${action}" title="${h(label)}"><span class="ni">${icon}</span><span class="label">${h(label)}</span></button>`;}
  function shell(body){const teacher=state.profile?.role==='teacher';root.innerHTML=`<div class="layout"><aside class="sidebar">
    <div class="logo"><span class="logo-mark">⌘</span> SiteArchitect <b>11</b></div><div><div class="side-caption">Моя майстерня</div>
    ${navLink('dashboard',teacher?'Кабінет учителя':'Мої роботи','▦',state.page==='dashboard')}
    ${!teacher?navLink('new-project','Новий проєкт','⊕',false):''}
    ${state.page==='editor'?navLink('editor-back','Конструктор','⌘',true):''}
    </div><div class="side-bottom"><small>${demo?'Демонстраційний режим':teacher?'Профіль учителя':'Профіль учня'}</small><strong>${h(state.profile?.full_name)}</strong><small>${h(state.profile?.class_name||'Кабінет учителя')}</small><button class="btn sm ghost full" style="margin-top:10px" data-action="logout">Вийти</button></div>
    </aside><main class="main"><div class="topbar"><div class="crumb">SiteArchitect 11 <span class="muted"> / </span> <strong>${teacher?'Teacher Studio':'Student Studio'}</strong></div><div class="top-right"><span class="pill">${demo?'◌ ДЕМО':'● Онлайн'}</span><button class="btn sm ghost" data-action="logout">Вийти ↗</button></div></div>${body}</main></div>`;}
  function render(){if(!state.profile){renderAuth();return;}if(state.page==='editor'){renderEditor();return;}if(state.page==='detail'){renderTeacherDetail();return;}if(state.profile.role==='teacher')renderTeacherDashboard();else renderStudentDashboard();}
  function workCard(w){const p=w.project||emptyWork(),a=analysis(p);return `<div class="work-card"><div><div class="btn-row"><span class="status ${w.status==='submitted'?'done':'draft'}">${w.status==='submitted'?'✓ Здано':'◌ Чернетка'}</span><span class="small muted">${fmtDate(w.updated_at)}</span></div><h4>${h(p.name||'Без назви')}</h4><p>${h(kindLabels[p.kind]||'Тип ще не обрано')} · ${a.pages} сторінок · Готовність ${a.score}%</p></div><div class="work-actions"><button class="btn sm blue" data-action="edit-work" data-id="${h(w.id)}">Відкрити →</button><button class="btn sm ghost" data-action="export-work" data-id="${h(w.id)}">↓ PNG</button><button class="btn sm danger" data-action="delete-work" data-id="${h(w.id)}" title="Видалити роботу">✕</button></div></div>`;}
  function renderStudentDashboard(){const works=[...state.works].sort((a,b)=>new Date(b.updated_at)-new Date(a.updated_at));const done=works.filter(x=>x.status==='submitted').length;shell(`<section class="hero"><span class="eyebrow">◈ Лабораторія вебархітектури</span>
    <h1 class="heading">Привіт, ${h((state.profile.full_name||'архітектор').split(' ')[0])}! <span>Плануємо сайт?</span></h1>
    <p class="desc">Твоя місія: спроєктувати зручну інформаційну структуру майбутнього вебсайту. Почни з ідеї, продумай вміст сторінок, створи розділи та згенеруй карту навігації.</p><div class="btn-row"><button class="btn primary" data-action="new-project">+ Створити вебпроєкт</button><span class="pill">Практична робота · 11 клас</span></div></section>
    ${demo?'<div class="notice warn" style="margin-bottom:17px">Це локальне демо. Учитель не отримає роботу автоматично; для спільного доступу необхідно підключити базу даних.</div>':''}
    <div class="grid3" style="margin-bottom:20px"><div class="stat"><small>Мої проєкти</small><b>${works.length}</b><small>Збережено</small></div><div class="stat"><small>Завершено</small><b>${done}</b><small>Надіслано вчителю</small></div><div class="stat"><small>У процесі</small><b>${works.length-done}</b><small>Можна редагувати</small></div></div>
    <section class="card"><div class="editor-heading"><div><h2 class="h2">Мої вебпроєкти</h2><p class="desc">Повернися до чернетки або відкрий готову роботу.</p></div></div>${works.length?works.map(workCard).join(''):`<div class="empty"><span class="empty-ico">⌘</span><h3>Поки що жодного проєкту</h3>Обери шаблон і створюй своє перше дерево сайту!</div>`}</section>
    <section style="margin-top:22px"><h2 class="h2">Швидкий старт: обери ідею</h2><p class="desc">Усі шаблони можна повністю змінити. Це лише стартова точка.</p><div class="grid4">${templateCards()}</div></section>`);}
  function templateCards(){return [{id:'portfolio',icon:'✦',name:'Моє портфоліо',desc:'Роботи, досягнення та контакти'},{id:'education',icon:'▤',name:'Освітній ресурс',desc:'Предмети, уроки, матеріали'},{id:'shop',icon:'◈',name:'Інтернет-магазин',desc:'Каталог, товари, кошик'},{id:'blog',icon:'▧',name:'Авторський блог',desc:'Статті, теми, рубрики'}].map(t=>`<button class="template-card" data-action="create-template" data-template="${t.id}"><span class="template-icon">${t.icon}</span><strong>${t.name}</strong><span>${t.desc}</span><span style="color:var(--lime);margin-top:auto;padding-top:13px">Вибрати →</span></button>`).join('');}
  function newProject(t='blank'){state.work={id:null,project:templates(t),status:'draft'};state.selected='home';state.step=0;state.page='editor';render();window.scrollTo(0,0);}
  function openProject(w){if(!w)return;state.work=clone(w);state.selected='home';state.step=0;state.page='editor';render();window.scrollTo(0,0);}
  function pageHeader(label,subtitle){return `<div class="editor-heading"><div><span class="eyebrow">${h(label)}</span><h1 class="h2" style="font-size:26px;margin:7px 0">${h(state.work.project.name||'Новий вебпроєкт')}</h1><p class="desc">${h(subtitle)}</p></div><div class="btn-row"><span class="status ${state.work.status==='submitted'?'done':'draft'}">${state.work.status==='submitted'?'✓ Здано':'◌ Чернетка'}</span><button class="btn sm ghost" data-action="save-draft">Зберегти</button></div></div>`;}
  function renderEditor(){const p=state.work.project,a=analysis(p);const captions=['Спочатку визнач, для кого і для чого існуватиме сайт.','Склади зміст: які сторінки та блоки інформації потрібні?','Розклади сторінки по логічних папках і створи ієрархію.','Перевір дерево, навігацію, глибину й баланс розділів.','Заверши проєкт, завантаж схему й передай роботу вчителю.'];
    const stepBar=`<div class="steps">${steps.map((s,i)=>`<button class="step ${i===state.step?'active':i<state.step?'completed':''}" data-action="go-step" data-step="${i}"><span class="step-num">${i<state.step?'✓':i+1}</span>${s}</button>`).join('')}</div>`;
    let section = state.step===0?stepPassport(p):state.step===1?stepContent(p):state.step===2?stepGroup(p):state.step===3?stepTree(p,a):stepResult(p,a);
    const footer=`<div class="editor-footer"><button class="btn ghost" data-action="go-step" data-step="${Math.max(0,state.step-1)}" ${state.step===0?'disabled':''}>← Назад</button><div class="btn-row"><span class="small muted">Крок ${state.step+1} з 5</span>${state.step<4?`<button class="btn primary" data-action="go-step" data-step="${state.step+1}">Далі →</button>`:`<button class="btn primary" data-action="submit-work">✓ Здати роботу</button>`}</div></div>`;
    shell(`${pageHeader('Конструктор структури',captions[state.step])}${stepBar}${section}${footer}`);}
  function inputField(label,name,value,placeholder='',opts={}){return `<div class="field"><label for="f-${name}">${label}</label>${opts.textarea?`<textarea id="f-${name}" data-field="${name}" placeholder="${h(placeholder)}" maxlength="${opts.max||500}" rows="3">${h(value)}</textarea>`:`<input id="f-${name}" data-field="${name}" maxlength="${opts.max||130}" placeholder="${h(placeholder)}" value="${h(value)}"/>`}</div>`;}
  function selectField(label,name,value,options){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" data-field="${name}">${Object.entries(options).map(([k,v])=>`<option value="${h(k)}" ${value===k?'selected':''}>${h(v)}</option>`).join('')}</select></div>`;}
  function stepPassport(p){return `<div class="split"><section class="card"><span class="eyebrow">01 / Концепція</span><h2 class="h2">Паспорт майбутнього сайту</h2><div class="form-grid">
    ${inputField('Назва вебсайту *','name',p.name,'Наприклад: Digital Universe')}
    ${selectField('Тип вебсайту *','kind',p.kind,{'':'Оберіть тип...',...kindLabels})}
    </div>${inputField('Тема / ідея сайту *','topic',p.topic,'Про що буде цей ресурс?')}
    ${inputField('Головна мета *','goal',p.goal,'Що має зробити користувач? Чого досягти?',{textarea:true,max:600})}
    ${inputField('Цільова аудиторія *','audience',p.audience,'Хто користуватиметься сайтом? Вік, інтереси, потреби')}
    <div class="form-grid">${selectField('Тип структури','structure',p.structure,structureLabels)}${selectField('Принцип групування','organize',p.organize,orgLabels)}</div>
    <div class="notice">Автор: <b>${h(state.profile.full_name)}</b> · Клас: <b>${h(state.profile.class_name)}</b>. Ці дані будуть додані до роботи.</div></section>
    <aside class="stack"><div class="card glow"><span class="eyebrow">Підказка архітектора</span><h2 class="h2" style="margin-top:8px">Спочатку користувач, потім сторінки</h2><p class="desc">Вдалий сайт починається з розуміння його відвідувачів. Мета має пояснювати не лише <i>про що</i> ресурс, а й <i>навіщо</i> він потрібен.</p>
    <div class="explainer"><b>Наприклад</b><p class="small muted">Тема: туристичні маршрути Вінниччини.<br/>Мета: допомогти підліткам швидко обрати маршрут вихідного дня.<br/>Аудиторія: учні 14–18 років та їхні друзі.</p></div></div>
    <div class="card"><h3 class="h3">Види інформаційної структури</h3><div class="tagrow"><span class="tag lime">Ієрархічна</span><span class="tag">Лінійна</span><span class="tag">Мережева</span><span class="tag">Гібридна</span></div><p class="small muted">Усі типи можна моделювати на базі дерева; для гібридної та мережевої структури додай додаткові переходи на кроці 4.</p></div></aside></div>`;}
  function outline(p, selectable=true){const visible=flatTree(p);return visible.map(({node,depth})=>`<button class="outline-item ${state.selected===node.id?'selected':''}" style="--depth:${depth}" data-action="select-node" data-id="${h(node.id)}"><span class="icon">${node.type==='home'?'⌂':node.type==='folder'?'▣':'▤'}</span><span class="name" style="flex:1">${h(node.label)}<small style="display:block">${node.type==='folder'?'Розділ':node.type==='home'?'Корінь':'Сторінка'}</small></span><span class="tiny muted">›</span></button>`).join('');}
  function nodeDetail(p){const n=getNode(p,state.selected)||getNode(p,'home');const blocks=(n.blocks||[]).map((b,i)=>`<div class="block-row"><span>${h(b)}</span><button class="btn sm ghost icon-only" data-action="remove-block" data-idx="${i}" aria-label="Прибрати блок">×</button></div>`).join('');return `<div><div class="btn-row" style="margin-bottom:14px"><span class="pill">${n.type==='home'?'⌂ Головна':n.type==='folder'?'▣ Розділ / папка':'▤ Сторінка'}</span><span class="small muted">${h(filePath(p,n.id))}</span></div>
    ${inputField('Назва *','node-title',n.label,'Назва сторінки або розділу')}${inputField('Короткий опис матеріалу *','node-description',n.description,'Яку інформацію знайде користувач?',{textarea:true,max:350})}
    ${n.type!=='folder'?`<h3 class="h3">Блоки вмісту <span class="muted small">(щонайменше 2)</span></h3><p class="small muted">Наприклад: заголовок, галерея, відео, текст, контакти, форма, картки…</p>
    <div>${blocks||'<p class="small muted">Ще немає блоків. Додай перший!</p>'}</div>
    <div class="add-inline"><input class="select" id="new-block" maxlength="90" placeholder="Назва нового блока" /><button class="btn sm blue" data-action="add-block">+ Додати</button></div>`:`<div class="notice">Папка логічно об’єднує сторінки. Додати їх до розділу можна на наступному кроці.</div>`}
    ${n.type!=='home'?`<hr class="sep"/><button class="btn sm danger" data-action="remove-node">Видалити ${n.type==='folder'?'розділ':'сторінку'}</button>`:''}</div>`;}
  function stepContent(p){return `<div class="split"><section class="card"><div class="editor-heading"><div><span class="eyebrow">02 / Складові</span><h2 class="h2">Сторінки й блоки вмісту</h2><p class="desc">Створи не менше 5 змістовних сторінок. Кожна має власне призначення.</p></div></div>
    <div class="btn-row" style="margin-bottom:14px"><button class="btn sm primary" data-action="add-page">+ Сторінка</button><button class="btn sm ghost" data-action="add-folder">+ Папка</button></div>
    <div class="outline-list">${outline(p)}</div><div class="tip-card"><strong>✦ З чого почати?</strong><p>Спочатку випиши всі сторінки. Групувати їх по розділах зможеш на кроці 3. Пам’ятай про головну сторінку, пошук інформації та зворотний зв’язок.</p></div></section>
    <section class="card"><h2 class="h2">Редактор елемента</h2><p class="desc">Вибери елемент зліва, а потім опиши, що він міститиме.</p>${nodeDetail(p)}</section></div>`;}
  function parentsOptions(p,n){return p.nodes.filter(x=>(x.type==='home'||x.type==='folder')&&x.id!==n.id&&!isDescendant(p,x.id,n.id)).map(x=>`<option value="${h(x.id)}" ${n.parentId===x.id?'selected':''}>${h(x.type==='home'?'⌂ Головна':`▣ ${x.label}`)}</option>`).join('');}
  function stepGroup(p){return `<div class="split"><section class="card"><span class="eyebrow">03 / Ієрархія</span><h2 class="h2">Згрупуй сторінки логічно</h2><p class="desc">Для кожного елемента обери батьківську папку. Стрілки змінюють порядок у межах одного розділу.</p>
    <div class="btn-row" style="margin-bottom:15px"><button class="btn sm primary" data-action="add-folder">+ Новий розділ</button><button class="btn sm ghost" data-action="add-page">+ Сторінка</button></div>
    ${p.nodes.filter(n=>n.id!=='home').length?p.nodes.filter(n=>n.id!=='home').map(n=>`<div class="group-row"><div><b>${n.type==='folder'?'▣':'▤'} ${h(n.label)}</b><small>${h(filePath(p,n.id))}</small></div><div class="field"><label>Розмістити всередині</label><select data-parent="${h(n.id)}">${parentsOptions(p,n)}</select></div><div class="arrows"><button class="btn sm ghost icon-only" title="Вище" data-action="order-up" data-id="${h(n.id)}">↑</button><button class="btn sm ghost icon-only" title="Нижче" data-action="order-down" data-id="${h(n.id)}">↓</button></div></div>`).join(''):'<div class="empty">Спочатку додай сторінки на попередньому кроці.</div>'}</section>
    <aside class="stack"><div class="card"><h3 class="h3">Поточна ієрархія</h3><div class="outline-list">${outline(p)}</div></div><div class="card glow"><span class="eyebrow">Принципи з уроку</span><h3 class="h3" style="margin-top:9px">Уникай «хмарочоса»</h3><p class="small muted">Ієрархія має бути зрозумілою. Для навчального проєкту орієнтуйся на доступність потрібної сторінки за 3 переходи від головної.</p><p class="small muted">Перевір, чи немає порожніх категорій і розділів, що містять більшість контенту, тоді як решта майже порожні.</p></div></aside></div>`;}
  function stepTree(p,a){const pageOptions=p.nodes.filter(n=>n.type==='page'||n.type==='home').map(n=>`<option value="${h(n.id)}">${h(n.label)}</option>`).join('');return `<div class="stack"><div class="grid2"><div class="card"><span class="eyebrow">04 / Візуальна модель</span><h2 class="h2">Живе дерево сайту</h2><p class="desc">Кожна зміна структури автоматично впливає на схему. Кольори розділяють головну, папки та сторінки.</p>
    <div class="grid3"><div class="stat"><small>Сторінок</small><b>${a.pages}</b></div><div class="stat"><small>Розділів</small><b>${a.folders}</b></div><div class="stat"><small>Глибина</small><b>${a.maxDepth}</b></div></div>
    <div class="btn-row" style="margin-top:14px"><button class="btn sm blue" data-action="download-png">↓ Завантажити PNG</button><button class="btn sm ghost" data-action="download-json">↓ JSON проєкту</button></div></div>
    <div class="card"><h2 class="h2">Поради цифрового архітектора</h2><p class="desc">Програма перевіряє структуру й пояснює, що можна покращити.</p>${a.warnings.length?a.warnings.slice(0,5).map(w=>`<div class="notice warn" style="margin-bottom:8px">⚠ ${h(w)}</div>`).join(''):'<div class="notice good">✓ Проблем із логікою структури не виявлено. Продовжуй!</div>'}
    <div class="notice" style="margin-top:10px">Правило «3 кліків» — навчальний орієнтир з презентації, а не абсолютна вимога до всіх реальних сайтів.</div></div></div>
    <div class="card"><div class="editor-heading"><div><h2 class="h2">Карта сторінок · ${h(p.name||'Мій сайт')}</h2><p class="desc">Схему можна прокручувати горизонтально, якщо вона широка.</p></div><span class="pill">SVG → PNG</span></div><div class="tree-view" id="tree-render">${makeSvg(p, state.profile)}</div><div class="legend"><span><i class="legend-dot" style="background:#b6f66a"></i>Головна</span><span><i class="legend-dot" style="background:#73afff"></i>Категорія / папка</span><span><i class="legend-dot" style="background:#b2c8e0"></i>Сторінка</span></div></div>
    <div class="card"><h2 class="h2">Перехресні посилання <span class="small muted">(за потреби)</span></h2><p class="desc">Щоб змоделювати гібридну чи мережеву структуру, додай переходи між різними сторінками. На схемі вони показані пунктиром.</p>
    <div class="form-grid"><div class="field"><label>Зі сторінки</label><select id="link-from">${pageOptions}</select></div><div class="field"><label>На сторінку</label><select id="link-to">${pageOptions}</select></div></div><button class="btn sm blue" data-action="add-link">+ Додати перехід</button>
    <div class="tagrow" style="margin-top:14px">${(p.links||[]).map((link,i)=>`<span class="tag">${h(getNode(p,link.from)?.label||'?')} ↗ ${h(getNode(p,link.to)?.label||'?')} <button data-action="remove-link" data-idx="${i}" class="btn sm ghost icon-only" style="min-height:25px;padding:1px 6px;margin-left:4px">×</button></span>`).join('')}</div></div></div>`;}
  function stepResult(p,a){return `<div class="split"><div class="stack"><div class="card glow"><span class="eyebrow">05 / Фінальна перевірка</span><h2 class="h2">Паспорт проєкту</h2>${[['Автор',state.profile.full_name],['Клас',state.profile.class_name],['Назва',p.name||'Не вказано'],['Тема',p.topic||'Не вказано'],['Мета',p.goal||'Не вказано'],['Аудиторія',p.audience||'Не вказано'],['Тип сайту',kindLabels[p.kind]||'Не визначено'],['Структура',structureLabels[p.structure]],['Групування',orgLabels[p.organize]],['Сторінки / папки',`${a.pages} / ${a.folders}`]].map(([k,v])=>`<div class="summary-kv"><span>${h(k)}</span><strong>${h(v)}</strong></div>`).join('')}</div>
    <div class="card"><h2 class="h2">Експорт проєкту</h2><p class="desc">Збережи зображення, яке можна додати до презентації або роздрукувати. JSON дає змогу зберегти структуру як дані.</p><div class="btn-row"><button class="btn primary" data-action="download-png">↓ Схема PNG</button><button class="btn ghost" data-action="download-json">↓ Проєкт JSON</button></div></div></div>
    <div class="stack"><div class="card"><div class="btn-row" style="margin-bottom:16px;justify-content:space-between"><div><span class="eyebrow">Готовність роботи</span><h2 class="h2">Чекліст вебархітектора</h2></div><div class="score-ring" style="--pct:${a.score}%"><span>${a.score}%</span></div></div>
    <div class="check-list">${a.specs.map(c=>`<div class="check ${c.ok?'ok':'warn'}"><span class="check-icon">${c.ok?'✅':'◯'}</span><div><strong>${h(c.name)}</strong><p>${h(c.detail)}</p></div></div>`).join('')}</div></div>
    <div class="card"><h2 class="h2">Передати роботу вчителю</h2><p class="desc">Зберегти можна будь-яку чернетку. Позначка «Здано» з’явиться після завершення обов’язкових пунктів.</p>
    ${!validForSubmit(p)?'<div class="notice warn" style="margin-bottom:12px">Поки що не всі обов’язкові умови виконано. Перевір паспорт, щонайменше 5 сторінок, їхні описи й блоки, глибину та назви.</div>':'<div class="notice good" style="margin-bottom:12px">Усі обов’язкові умови виконано. Роботу можна здати!</div>'}
    <div class="btn-row"><button class="btn ghost" data-action="save-draft">◌ Зберегти чернетку</button><button class="btn primary" data-action="submit-work" ${validForSubmit(p)?'':'disabled'}>✓ ${state.work.status==='submitted'?'Оновити здану роботу':'Здати роботу'}</button></div>
    <p class="small muted" style="margin-top:14px">${demo?'У деморежимі «Здати роботу» лише збереже її локально.':'Після здачі вчитель побачить проєкт у своєму кабінеті. Редагувати його можна й після здачі.'}</p></div></div></div>`;}
  function makeSvg(p, author){
    const ordered=flatTree(p), map=new Map(), nodeW=206, nodeH=82, hGap=22, levelGap=166, margin=54, headerH=157;
    if(!ordered.length)return '';
    const spanOf=(id)=>{const kids=children(p,id);return kids.length?Math.max(nodeW,kids.reduce((s,n)=>s+spanOf(n.id),0)+(kids.length-1)*hGap):nodeW;};
    function position(id,start,depth){const w=spanOf(id),kids=children(p,id),childSpan=kids.reduce((s,n)=>s+spanOf(n.id),0)+Math.max(0,kids.length-1)*hGap;let offset=start+(w-childSpan)/2;
      if(kids.length){for(const c of kids){const sw=spanOf(c.id);position(c.id,offset,depth+1);offset+=sw+hGap;}const first=map.get(kids[0].id),last=map.get(kids[kids.length-1].id);map.set(id,{x:(first.x+last.x)/2,y:headerH+depth*levelGap,depth});}
      else map.set(id,{x:start+w/2,y:headerH+depth*levelGap,depth});}
    const width=Math.max(840,spanOf('home')+margin*2);const start=(width-spanOf('home'))/2;position('home',start,0);
    const maxDepth=Math.max(...ordered.map(o=>o.depth));const height=headerH+(maxDepth+1)*levelGap+85;
    const wrap=(text,max=20,lines=2)=>{let words=String(text||'').split(/\s+/),out=[],row='';for(const word of words){if((row+' '+word).trim().length>max &&row){out.push(row);row=word;}else row=(row+' '+word).trim();}if(row)out.push(row);if(out.length>lines){out=out.slice(0,lines);out[lines-1]=out[lines-1].slice(0,max-1)+'…';}return out;};
    const textLines=(text,x,y,fill,size=14,weight=700,max=23,lines=2)=>wrap(text,max,lines).map((str,i)=>`<text x="${x}" y="${y+i*(size+5)}" text-anchor="middle" font-size="${size}" font-weight="${weight}" fill="${fill}">${h(str)}</text>`).join('');
    const edges=[];const cards=[];
    for(const {node} of ordered){const a=map.get(node.id);if(!a)continue;
      if(node.parentId){const b=map.get(node.parentId);if(b){const x1=b.x,y1=b.y+nodeH/2,x2=a.x,y2=a.y-nodeH/2;edges.push(`<path d="M ${x1} ${y1} C ${x1} ${y1+43}, ${x2} ${y2-43}, ${x2} ${y2}" fill="none" stroke="#6687a4" stroke-width="2.5" opacity=".87"/>`);}}
      const home=node.type==='home',folder=node.type==='folder',fill=home?'#224f3d':folder?'#194365':'#1b304b',stroke=home?'#b6f66a':folder?'#73afff':'#668aab',symbol=home?'⌂':folder?'▣':'▤';
      const desc=wrap(node.description||'',28,1)[0]||'Опис не додано';
      cards.push(`<g><rect x="${a.x-nodeW/2+3}" y="${a.y-nodeH/2+5}" width="${nodeW}" height="${nodeH}" rx="14" fill="#05101c" opacity=".65"/><rect x="${a.x-nodeW/2}" y="${a.y-nodeH/2}" width="${nodeW}" height="${nodeH}" rx="14" fill="${fill}" stroke="${stroke}" stroke-width="${home?2.8:1.9}"/>
       <rect x="${a.x-nodeW/2+12}" y="${a.y-nodeH/2+11}" width="25" height="25" rx="7" fill="${home?'#b6f66a':folder?'#73afff':'#b2c8e0'}"/><text x="${a.x-nodeW/2+24.5}" y="${a.y-nodeH/2+29}" text-anchor="middle" font-size="16" font-weight="700" fill="#102234">${symbol}</text>
       ${textLines(node.label,a.x+13,a.y-9,'#f1f7ff',13.6,800,18,2)}<text x="${a.x}" y="${a.y+24}" text-anchor="middle" font-size="10.5" fill="#afc2d9">${h(desc.slice(0,34))}</text></g>`);
    }
    const cross=[];for(const link of p.links||[]){const a=map.get(link.from),b=map.get(link.to);if(!a||!b||link.from===link.to)continue;const slope=a.x>b.x?-1:1;const ax=a.x+slope*nodeW/2,ay=a.y,bx=b.x-slope*nodeW/2,by=b.y;const mid=(ax+bx)/2;cross.push(`<path d="M ${ax} ${ay} Q ${mid} ${Math.min(ay,by)-75} ${bx} ${by}" fill="none" stroke="#ffbd70" stroke-width="2.5" stroke-dasharray="8 6" marker-end="url(#arrow)"/>`);}
    return `<svg xmlns="http://www.w3.org/2000/svg" width="${Math.ceil(width)}" height="${Math.ceil(height)}" viewBox="0 0 ${Math.ceil(width)} ${Math.ceil(height)}" role="img" aria-label="Карта інформаційної структури сайту"><defs><pattern id="dots" width="25" height="25" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1" fill="#456078" opacity=".35"/></pattern><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M1 1 L7 4 L1 7" stroke="#ffbd70" stroke-width="1.2" fill="none"/></marker></defs>
    <rect width="100%" height="100%" fill="#0c192b"/><rect width="100%" height="100%" fill="url(#dots)"/>
    <rect width="${width}" height="7" fill="#b6f66a"/><text x="${width/2}" y="48" text-anchor="middle" font-family="Arial,sans-serif" font-size="26" font-weight="bold" fill="#f1f7ff">${h((p.name||'Інформаційна структура сайту').slice(0,65))}</text>
    <text x="${width/2}" y="76" text-anchor="middle" font-family="Arial,sans-serif" font-size="14" fill="#aabed4">Інформаційна архітектура • ${h(structureLabels[p.structure]||'Ієрархічна')} структура</text>
    <text x="${width/2}" y="102" text-anchor="middle" font-family="Arial,sans-serif" font-size="13" fill="#b6f66a">Автор: ${h((author?.full_name||'Учень').slice(0,70))} · ${h((author?.class_name||'11 клас').slice(0,25))}</text>
    <g font-family="Arial,sans-serif">${edges.join('')}${cross.join('')}${cards.join('')}</g><text x="${width-30}" y="${height-26}" text-anchor="end" font-size="11" fill="#809bb8" font-family="Arial,sans-serif">SiteArchitect 11</text></svg>`;
  }
  async function downloadPNG(p,author){try{const svg=makeSvg(p,author);const img=new Image();const blob=new Blob([svg],{type:'image/svg+xml;charset=utf-8'});const url=URL.createObjectURL(blob);const size=svg.match(/viewBox="0 0 (\d+) (\d+)"/);const w=Number(size?.[1]||1200),ht=Number(size?.[2]||700);const scale=w>3500?1:2;
      img.onload=()=>{try{const canvas=document.createElement('canvas');canvas.width=w*scale;canvas.height=ht*scale;const ctx=canvas.getContext('2d');ctx.fillStyle='#0c192b';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.scale(scale,scale);ctx.drawImage(img,0,0);canvas.toBlob(file=>{if(file)saveBlob(file,`SiteArchitect_${safeFilename(author?.full_name)}_${safeFilename(p.name)}.png`);else toast('Не вдалося експортувати зображення.',true);URL.revokeObjectURL(url);},'image/png');}catch(err){URL.revokeObjectURL(url);toast('Помилка створення PNG: '+err.message,true);}};
      img.onerror=()=>{URL.revokeObjectURL(url);toast('Не вдалося перетворити схему в PNG.',true);};img.src=url;
    }catch(e){toast('Помилка експорту: '+e.message,true);}}
  function saveBlob(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
  function downloadJSON(p,author){const content={version:1,exportedAt:new Date().toISOString(),author:{name:author?.full_name||'',className:author?.class_name||''},project:p};saveBlob(new Blob([JSON.stringify(content,null,2)],{type:'application/json;charset=utf-8'}),`SiteArchitect_${safeFilename(author?.full_name)}.json`);}
  function renderTeacherDashboard(){const works=state.teacherWorks,submitted=works.filter(x=>x.status==='submitted'),classes=[...new Set(state.profiles.map(p=>p.class_name).filter(Boolean))].sort();shell(`<section class="hero"><span class="eyebrow">◇ Teacher Studio</span><h1 class="heading">Кабінет <span>учителя</span></h1>
    <p class="desc">Усі учнівські проєкти в одному місці. Переглядайте схеми, аналізуйте структури, завантажуйте PNG та експортуйте результати.</p><div class="btn-row"><button class="btn primary" data-action="refresh-teacher">↻ Оновити роботи</button><button class="btn ghost" data-action="export-csv">↓ Експорт CSV</button></div></section>
    <div class="grid3" style="margin-bottom:20px"><div class="stat"><small>Усього збережено</small><b>${works.length}</b><small>Усі статуси</small></div><div class="stat"><small>Здані роботи</small><b>${submitted.length}</b><small>Можна перевіряти</small></div><div class="stat"><small>Учнів із роботами</small><b>${new Set(works.map(w=>w.owner_id)).size}</b><small>Унікальних авторів</small></div></div>
    <section class="card"><div class="editor-heading"><div><h2 class="h2">Реєстр виконаних робіт</h2><p class="desc">За замовчуванням показано тільки здані роботи. Чернетки теж можна переглянути.</p></div></div>
    <div class="teacher-toolbar"><input id="teacher-search" aria-label="Пошук учня чи проєкту" placeholder="Пошук за ім’ям, класом або назвою сайту..." value="${h(state.teacherQuery)}"/>
    <select id="teacher-class" aria-label="Фільтр за класом"><option value="all">Усі класи</option>${classes.map(c=>`<option ${state.teacherClass===c?'selected':''} value="${h(c)}">${h(c)}</option>`).join('')}</select>
    <select id="teacher-status" aria-label="Фільтр за статусом"><option value="submitted" ${state.teacherStatus==='submitted'?'selected':''}>Лише здані</option><option value="draft" ${state.teacherStatus==='draft'?'selected':''}>Чернетки</option><option value="all" ${state.teacherStatus==='all'?'selected':''}>Усі статуси</option></select></div>
    <div id="teacher-results">${teacherTable()}</div></section>`);}
  function authorOf(ownerId){return state.profiles.find(p=>p.id===ownerId)||{full_name:'Невідомий учень',class_name:'—'};}
  function filteredTeacherWorks(){const q=state.teacherQuery.trim().toLowerCase();return state.teacherWorks.filter(w=>{const p=authorOf(w.owner_id);return (state.teacherStatus==='all'||w.status===state.teacherStatus)&&(state.teacherClass==='all'||p.class_name===state.teacherClass)&&(!q||[p.full_name,p.class_name,w.project?.name,w.project?.topic].some(t=>String(t||'').toLowerCase().includes(q)));});}
  function teacherTable(){const arr=filteredTeacherWorks();return `<div class="teacher-table-wrap"><table class="teacher-table"><thead><tr><th>Учень</th><th>Проєкт</th><th>Статус</th><th>Оновлено</th><th>Дія</th></tr></thead><tbody>${arr.length?arr.map(w=>{const p=authorOf(w.owner_id),a=analysis(w.project||emptyWork());return `<tr><td><strong>${h(p.full_name)}</strong><small>${h(p.class_name)}</small></td><td><strong>${h(w.project?.name||'Без назви')}</strong><small>${a.pages} сторінок · ${a.score}% готовності</small></td><td><span class="status ${w.status==='submitted'?'done':'draft'}">${w.status==='submitted'?'✓ Здано':'◌ Чернетка'}</span></td><td class="small">${fmtDate(w.updated_at)}</td><td><button class="btn sm blue" data-action="teacher-open" data-id="${h(w.id)}">Переглянути →</button></td></tr>`;}).join(''):`<tr><td colspan="5"><div class="empty">Не знайдено робіт за вибраними фільтрами.</div></td></tr>`}</tbody></table></div><p class="small muted" style="margin:9px 0 0">Показано ${arr.length} із ${state.teacherWorks.length} збережених робіт</p>`;}
  function renderTeacherDetail(){const w=state.viewed;if(!w){state.page='dashboard';render();return;}const p=w.project||emptyWork(),a=analysis(p),author=authorOf(w.owner_id);shell(`<div class="btn-row" style="margin-bottom:16px"><button class="btn ghost" data-action="dashboard">← Усі роботи</button><span class="status ${w.status==='submitted'?'done':'draft'}">${w.status==='submitted'?'✓ Здано':'◌ Чернетка'}</span></div>
    <section class="hero"><span class="eyebrow">Перегляд учнівської роботи</span><h1 class="heading">${h(p.name||'Без назви')}</h1><p class="desc"><strong>${h(author.full_name)}</strong> · ${h(author.class_name)} · Оновлено ${fmtDate(w.updated_at)}</p><div class="btn-row"><button class="btn primary" data-action="teacher-png">↓ Завантажити PNG</button><button class="btn ghost" data-action="teacher-json">↓ Завантажити JSON</button></div></section>
    <div class="grid3" style="margin-bottom:19px"><div class="stat"><small>Сторінок</small><b>${a.pages}</b></div><div class="stat"><small>Макс. глибина</small><b>${a.maxDepth}</b></div><div class="stat"><small>Готовність чекліста</small><b>${a.score}%</b></div></div>
    <div class="card" style="margin-bottom:17px"><h2 class="h2">Структура сайту</h2><div class="tree-view">${makeSvg(p,author)}</div><div class="legend"><span><i class="legend-dot" style="background:#b6f66a"></i>Головна</span><span><i class="legend-dot" style="background:#73afff"></i>Категорія</span><span><i class="legend-dot" style="background:#b2c8e0"></i>Сторінка</span></div></div>
    <div class="grid2"><div class="card"><h2 class="h2">Концепція</h2>${[['Тема',p.topic],['Мета',p.goal],['Аудиторія',p.audience],['Тип',kindLabels[p.kind]],['Структура',structureLabels[p.structure]],['Принцип групування',orgLabels[p.organize]]].map(([k,v])=>`<div class="summary-kv"><span>${h(k)}</span><strong>${h(v||'—')}</strong></div>`).join('')}</div>
    <div class="card"><h2 class="h2">Зміст сторінок</h2>${flatTree(p).filter(({node})=>node.type!=='folder').map(({node,depth})=>`<div class="card inset" style="margin-bottom:9px"><strong>${'↳ '.repeat(depth)}${h(node.label)}</strong><p class="small muted" style="margin:3px 0">${h(node.description||'Опис відсутній')}</p><div class="tagrow">${(node.blocks||[]).map(b=>`<span class="tag">${h(b)}</span>`).join('')}</div><small class="muted">${h(filePath(p,node.id))}</small></div>`).join('')}</div></div>
    <div class="card" style="margin-top:17px"><h2 class="h2">Навчальний чекліст</h2><div class="grid2">${a.specs.map(c=>`<div class="check ${c.ok?'ok':'warn'}"><span>${c.ok?'✅':'◯'}</span><div><strong>${h(c.name)}</strong><p>${h(c.detail)}</p></div></div>`).join('')}</div><p class="small muted">Показник готовності автоматичний і не є оцінкою за 12-бальною шкалою. Остаточну оцінку визначає вчитель.</p></div>`);}
  function downloadCSV(){const rows=[['Учень','Клас','Проєкт','Тип','Тема','Статус','Сторінок','Розділів','Глибина','Готовність, %','Оновлено']];for(const w of filteredTeacherWorks()){const p=w.project||emptyWork(),a=analysis(p),au=authorOf(w.owner_id);rows.push([au.full_name,au.class_name,p.name,kindLabels[p.kind]||'',p.topic,w.status,a.pages,a.folders,a.maxDepth,a.score,fmtDate(w.updated_at)]);}const csv='\ufeff'+rows.map(row=>row.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(';')).join('\r\n');saveBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),'SiteArchitect_works.csv');}

  async function loadStudentWorks(){if(demo){try{state.works=JSON.parse(localStorage.getItem('sa11.works')||'[]');}catch{state.works=[];}return;}
    const {data,error}=await db.from('site_projects').select('id,owner_id,project,status,created_at,updated_at').order('updated_at',{ascending:false});if(error){toast('Не вдалося завантажити роботи: '+error.message,true);return;}state.works=data||[];}
  async function loadTeacherWorks(){const [w,p]=await Promise.all([
      db.from('site_projects').select('id,owner_id,project,status,created_at,updated_at').order('updated_at',{ascending:false}),
      db.from('profiles').select('id,full_name,class_name,role')]);
    if(w.error||p.error)throw new Error(w.error?.message||p.error?.message);state.teacherWorks=w.data||[];state.profiles=p.data||[];}
  async function loadProfile(){if(demo)return;const {data:{user},error:authErr}=await db.auth.getUser();if(authErr||!user){state.user=null;state.profile=null;render();return;}state.user=user;
    const {data, error}=await db.from('profiles').select('id,full_name,class_name,role').eq('id',user.id).single();
    if(error||!data){state.profile=null;state.authError='Профіль не знайдено. Перевірте, чи виконано SQL-файл schema.sql. '+(error?.message||'');render();return;}
    state.profile=data;state.page='dashboard';if(data.role==='teacher')await loadTeacherWorks();else await loadStudentWorks();render();}
  async function saveWork(status='draft'){if(!state.work||state.busy)return false;const p=clone(state.work.project);const effective=(state.work.status==='submitted'&&status==='draft')?'submitted':status;
    state.busy=true;try{let record;if(demo){const now=new Date().toISOString();record={...state.work,id:state.work.id||uid(),owner_id:'demo',project:p,status:effective,created_at:state.work.created_at||now,updated_at:now};const index=state.works.findIndex(w=>w.id===record.id);if(index<0)state.works.unshift(record);else state.works[index]=record;localStorage.setItem('sa11.works',JSON.stringify(state.works));}
      else{const payload={project:p,status:effective};let result;
        if(state.work.id)result=await db.from('site_projects').update({...payload,updated_at:new Date().toISOString()}).eq('id',state.work.id).eq('owner_id',state.user.id).select('id,owner_id,project,status,created_at,updated_at').single();
        else result=await db.from('site_projects').insert({...payload,owner_id:state.user.id}).select('id,owner_id,project,status,created_at,updated_at').single();
        if(result.error)throw result.error;record=result.data;const idx=state.works.findIndex(w=>w.id===record.id);if(idx<0)state.works.unshift(record);else state.works[idx]=record;}
      state.work=clone(record);toast(effective==='submitted'?(demo?'Роботу збережено локально як завершену!':'Роботу здано! Вона доступна вчителю.'):'Чернетку збережено.');return true;
    }catch(e){toast('Помилка збереження: '+(e.message||e),true);return false;}finally{state.busy=false;}}
  async function deleteWork(id){const w=state.works.find(w=>w.id===id);if(!w)return;if(!confirm(`Видалити проєкт «${w.project?.name||'Без назви'}»? Цю дію не можна скасувати.`))return;
    try{if(demo){state.works=state.works.filter(w=>w.id!==id);localStorage.setItem('sa11.works',JSON.stringify(state.works));}else{const{error}=await db.from('site_projects').delete().eq('id',id).eq('owner_id',state.user.id);if(error)throw error;state.works=state.works.filter(w=>w.id!==id);}render();toast('Роботу видалено.');}catch(e){toast(e.message,true);}}
  function mutateNodeField(key,value){const n=getNode(state.work.project,state.selected);if(!n)return;if(key==='node-title')n.label=clip(value,90);else if(key==='node-description')n.description=clip(value,350);}
  function addNode(type){const p=state.work.project;if(p.nodes.length>=45){toast('У цій навчальній версії дозволено не більше 45 елементів.',true);return;}const n=mkNode(type,type==='folder'?'Новий розділ':'Нова сторінка','home','',[]);n.order=children(p,'home').length;p.nodes.push(n);state.selected=n.id;state.step=1;render();toast('Елемент додано. Укажи назву й опис.');}
  function removeNode(){const p=state.work.project,n=getNode(p,state.selected);if(!n||n.id==='home')return;const subtree=p.nodes.filter(x=>x.id===n.id||isDescendant(p,x.id,n.id));if(!confirm(`Видалити «${n.label}»${subtree.length>1?' разом із вкладеними елементами':''}?`))return;const gone=new Set(subtree.map(n=>n.id));p.nodes=p.nodes.filter(x=>!gone.has(x.id));p.links=p.links.filter(x=>!gone.has(x.from)&&!gone.has(x.to));state.selected='home';render();toast('Елемент видалено.');}
  function changeParent(id,parentId){const p=state.work.project,n=getNode(p,id),parent=getNode(p,parentId);if(!n||!parent||n.id==='home'||!['home','folder'].includes(parent.type)||n.id===parentId||isDescendant(p,parentId,n.id))return;const sibling=children(p,parentId);n.parentId=parentId;n.order=sibling.length;render();}
  function moveOrder(id,dir){const p=state.work.project,n=getNode(p,id);if(!n)return;const sib=children(p,n.parentId),idx=sib.findIndex(x=>x.id===id),other=sib[idx+dir];if(!other)return;const ordered=sib.map(x=>x.id);[ordered[idx],ordered[idx+dir]]=[ordered[idx+dir],ordered[idx]];ordered.forEach((sid,i)=>getNode(p,sid).order=i);render();}
  function bindFormInputs(){root.addEventListener('input',e=>{const el=e.target,key=el.dataset.field;if(key&&state.work){if(key.startsWith('node-'))mutateNodeField(key,el.value);else state.work.project[key]=clip(el.value,key==='goal'?600:150);}
      if(el.id==='teacher-search'){state.teacherQuery=el.value;const area=document.getElementById('teacher-results');if(area)area.innerHTML=teacherTable();}});
    root.addEventListener('change',e=>{const el=e.target;if(el.dataset.parent){changeParent(el.dataset.parent,el.value);return;}if(el.id==='teacher-status'||el.id==='teacher-class'){if(el.id==='teacher-status')state.teacherStatus=el.value;else state.teacherClass=el.value;const area=document.getElementById('teacher-results');if(area)area.innerHTML=teacherTable();}});
    root.addEventListener('keydown',e=>{if(e.target.id==='new-block'&&e.key==='Enter'){e.preventDefault();const btn=root.querySelector('[data-action="add-block"]');btn?.click();}});
    root.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='demo-form'){const fd=new FormData(e.target);const full_name=String(fd.get('fullName')||'').trim(),class_name=String(fd.get('className')||'').trim();if(!full_name||!class_name){toast('Заповни ім’я та клас.',true);return;}state.profile={id:'demo',full_name,class_name,role:'student'};state.demoProfile=state.profile;localStorage.setItem('sa11.profile',JSON.stringify(state.profile));state.page='dashboard';await loadStudentWorks();render();return;}
      if(e.target.id==='auth-form'){const fd=new FormData(e.target),email=String(fd.get('email')||'').trim(),password=String(fd.get('password')||'');if(state.busy)return;state.busy=true;state.authMessage='';state.authError='';try{
          if(state.authMode==='signup'){const full_name=String(fd.get('fullName')||'').trim(),class_name=String(fd.get('className')||'').trim();if(!full_name||!class_name)throw new Error('Укажіть ім’я та клас.');const {data,error}=await db.auth.signUp({email,password,options:{data:{full_name,class_name},emailRedirectTo:location.href.split('#')[0]}});if(error)throw error;if(data.session){await loadProfile();toast('Обліковий запис створено.');return;}state.authMessage='Реєстрацію отримано. Якщо для проєкту ввімкнене підтвердження пошти, перевірте свою скриньку та перейдіть за посиланням.';}
          else{const {error}=await db.auth.signInWithPassword({email,password});if(error)throw error;await loadProfile();return;}
        }catch(err){state.authError=err.message||String(err);}finally{state.busy=false;}render();return;}
    });
    root.addEventListener('click',async e=>{const btn=e.target.closest('[data-action]');if(!btn||btn.disabled)return;const action=btn.dataset.action,p=state.work?.project;try{
      switch(action){
        case 'auth-mode':state.authMode=btn.dataset.mode;state.authError='';state.authMessage='';render();break;
        case 'reset-password':{if(!cloud)return;const email=prompt('Введіть адресу електронної пошти для відновлення пароля:');if(!email)return;const {error}=await db.auth.resetPasswordForEmail(email.trim(),{redirectTo:location.href.split('#')[0]});if(error)toast(error.message,true);else toast('Якщо обліковий запис існує, лист надійде на пошту (потрібен налаштований SMTP).');break;}
        case 'logout':if(cloud){await db.auth.signOut();state.user=null;}else{state.demoProfile=state.profile;localStorage.removeItem('sa11.profile');}state.profile=null;state.work=null;state.page='dashboard';render();break;
        case 'dashboard':case 'editor-back':state.page='dashboard';state.work=null;if(state.profile.role==='teacher')await loadTeacherWorks();else await loadStudentWorks();render();break;
        case 'new-project':newProject();break;
        case 'create-template':newProject(btn.dataset.template);break;
        case 'edit-work':openProject(state.works.find(w=>w.id===btn.dataset.id));break;
        case 'delete-work':await deleteWork(btn.dataset.id);break;
        case 'export-work':{const w=state.works.find(w=>w.id===btn.dataset.id);if(w)downloadPNG(w.project,state.profile);break;}
        case 'go-step':state.step=Number(btn.dataset.step);render();window.scrollTo({top:0,behavior:'smooth'});break;
        case 'select-node':state.selected=btn.dataset.id;render();break;
        case 'add-page':addNode('page');break;
        case 'add-folder':addNode('folder');break;
        case 'remove-node':removeNode();break;
        case 'add-block':{const input=document.getElementById('new-block');const val=input?.value.trim(),n=getNode(p,state.selected);if(!val){toast('Спочатку введи назву блока.',true);return;}if(n&&(n.blocks||[]).length<25){n.blocks.push(clip(val,90));render();}break;}
        case 'remove-block':{const n=getNode(p,state.selected);n?.blocks?.splice(Number(btn.dataset.idx),1);render();break;}
        case 'order-up':moveOrder(btn.dataset.id,-1);break;
        case 'order-down':moveOrder(btn.dataset.id,1);break;
        case 'add-link':{const from=document.getElementById('link-from')?.value,to=document.getElementById('link-to')?.value;if(!from||!to||from===to){toast('Обери дві різні сторінки.',true);return;}p.links=p.links||[];if(p.links.length>=30){toast('Доступно не більше 30 додаткових посилань.',true);return;}if(p.links.some(l=>l.from===from&&l.to===to)){toast('Таке посилання вже існує.',true);return;}p.links.push({from,to});render();break;}
        case 'remove-link':p.links.splice(Number(btn.dataset.idx),1);render();break;
        case 'save-draft':if(await saveWork('draft'))render();break;
        case 'submit-work':if(!validForSubmit(p)){state.step=4;render();toast('Заповни обов’язкові пункти чекліста.',true);return;}if(await saveWork('submitted')){state.step=4;render();}break;
        case 'download-png':downloadPNG(p,state.profile);break;
        case 'download-json':downloadJSON(p,state.profile);break;
        case 'refresh-teacher':await loadTeacherWorks();render();toast('Список робіт оновлено.');break;
        case 'export-csv':downloadCSV();break;
        case 'teacher-open':state.viewed=state.teacherWorks.find(w=>w.id===btn.dataset.id);state.page='detail';render();window.scrollTo(0,0);break;
        case 'teacher-png':downloadPNG(state.viewed.project,authorOf(state.viewed.owner_id));break;
        case 'teacher-json':downloadJSON(state.viewed.project,authorOf(state.viewed.owner_id));break;
      }
      }catch(err){toast(err?.message||String(err),true);}
    });
  }
  async function init(){bindFormInputs();if(configured&&!window.supabase){state.authError='Не вдалося завантажити бібліотеку Supabase. Перевірте інтернет-з’єднання та підключення CDN.';renderAuth();return;}
    if(demo){try{const prof=JSON.parse(localStorage.getItem('sa11.profile')||'null');if(prof&&prof.full_name&&prof.class_name){state.profile=prof;state.demoProfile=prof;await loadStudentWorks();}}catch{}render();return;}
    try{const {data:{session},error}=await db.auth.getSession();if(error)throw error;if(session)await loadProfile();else renderAuth();
      db.auth.onAuthStateChange((event)=>{if(event==='SIGNED_OUT'){state.user=null;state.profile=null;state.work=null;state.page='dashboard';render();}});
    }catch(err){state.authError='Проблема підключення: '+(err.message||err);renderAuth();}
  }
  init();
})();
